function ItemDB:GetCandidatesForSlot(slotKey)
	local Eligibility = JohnnysGearAdvisor.Eligibility
	local results = {}
	for _, item in ipairs(self.items) do
		if item.slot == slotKey and Eligibility:IsEligible(item, slotKey) then
			table.insert(results, item)
		end
	end
	return results
end
